// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface iBEP20X {
    function balanceOf(address) external view returns (uint256);
}

contract __InvMutPoolStub {
    C public c;
    uint256 public lp;
    constructor(C _c, uint256 _lp) { c = _c; lp = _lp; }
    function name() external pure returns (string memory) { return "P"; }
    function symbol() external pure returns (string memory) { return "P"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address who) external view returns (uint256) { return who == address(c) ? lp : 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
    function doMintSynth(uint256 amount) external returns (uint256) { return c.mintSynth(address(this), amount); }
}

contract __InvMutPoolFactory {
    function isCuratedPool(address) external pure returns (bool) { return true; }
}

contract InvMutTest is Test {
    C c;
    __InvMutPoolFactory poolFactory;

    function DAO() external view returns (iDAO) { return iDAO(address(this)); }
    function POOLFACTORY() external view returns (address) { return address(poolFactory); }

    function setUp() public {
        c = new C(address(this), address(new __InvMutHandleStub()));
        poolFactory = new __InvMutPoolFactory();
    }

    function testFuzz_property(uint256 amount, uint256 lp) public {
        vm.assume(lp > 0);
        amount = bound(amount, 1, type(uint128).max);
        lp = bound(lp, 1, type(uint128).max);
        __InvMutPoolPoolStubPlaceholder();
        __InvMutPoolFactoryPfDummy();
        __InvMutPoolStub pool = new __InvMutPoolStub(c, lp);
        pool.doMintSynth(amount);
        assertTrue(c.mapSynth_LPBalance(address(pool)) == iBEP20X(address(pool)).balanceOf(address(c)));
    }

    function __InvMutPoolPoolStubPlaceholder() internal pure {}
    function __InvMutPoolFactoryPfDummy() internal pure {}
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
